arguments.command:
cd /tmp/vally-eval-trial-bWfkTM && P=.copilot-tracking/skraft-plans/pricing && D=2026-11-11 && mkdir -p $P/features $P/details/$D $P/evidence/$D/discount tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $P/features/pricing-loyalty-discount.feature <<'E'
@loyalty-discount
Feature: Loyalty discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: Bronze, Silver, Gold (AC-1 to AC-4).
  # NOT DECIDED: Platinum. The business has not agreed a reduction, so no scenario
  # exists for it and none may be invented. Tracked as an open question, see the
  # "Open decisions" section at the end of this file.

  @happy-path @smoke
  Scenario: Bronze customer is charged 9500 cents for a 10000 cent basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged 9000 cents for a 10000 cent basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged 8500 cents for a 10000 cent basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer's reduction lands on a whole cent in the customer's favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents

  # Open decisions (not executable, awaiting DISCUSS):
  #   OPEN-1 Platinum tier: what reduction applies? No expected value exists.
  #          Platinum arrives next quarter and is out of scope for milestone M1.
E
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // Bronze customer is charged 9500 cents for a 10000 cent basket (AC-1)
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_tier_price(LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $P/evidence/$D/discount/acceptance-red.stdout 2>&1; echo $? > $P/evidence/$D/discount/acceptance-red.exit; git rev-parse HEAD > $P/evidence/$D/discount/acceptance-red.rev 2>&1; cat $P/evidence/$D/discount/acceptance-red.exit; tail -25 $P/evidence/$D/discount/acceptance-red.stdout; cat $P/evidence/$D/discount/acceptance-red.rev

